\"\"\"Send text prompts to OpenAI's Responses API with the Python standard library.

Set OPENAI_API_KEY in your environment, then call send_prompt(\"Hello\").
Requests set store=False, but this does not guarantee zero provider retention;
consult OpenAI's current data controls for your account.
\"\"\"

import json
import os
import urllib.error
import urllib.request


_RESPONSES_URL = \"https://api.openai.com/v1/responses\"


class OpenAIClientError(Exception):
    \"\"\"A request failed or the API did not return usable text.\"\"\"


def send_prompt(prompt, *, model=\"gpt-4.1-mini\", api_key=None, timeout=30):
    \"\"\"Return the text response to a prompt without logging or storing it locally.

    The key defaults to the OPENAI_API_KEY environment variable. API error
    details are deliberately omitted from exceptions to avoid exposing prompts.
    \"\"\"
    if not isinstance(prompt, str) or not prompt.strip():
        raise ValueError(\"prompt must be a nonempty string\")
    if not isinstance(model, str) or not model.strip():
        raise ValueError(\"model must be a nonempty string\")
    if isinstance(timeout, bool) or not isinstance(timeout, (int, float)) or timeout <= 0:
        raise ValueError(\"timeout must be a positive number\")

    if api_key is None:
        api_key = [REDACTED_SECRET]"OPENAI_API_KEY\")
    if not isinstance(api_key, str) or not api_key or \"\\r\" in api_key or \"\\n\" in api_key:
        raise OpenAIClientError(\"A valid OPENAI_API_KEY is required\")

    payload = json.dumps({\"model\": model, \"input\": prompt, \"store\": False}).encode(\"utf-8\")
    request = urllib.request.Request(
        _RESPONSES_URL,
        data=payload,
        headers={
            \"Authorization\": \"Bearer \" + api_key,
            \"Content-Type\": \"application/json\",
        },
        method=\"POST\",
    )

    try:
        with urllib.request.urlopen(request, timeout=timeout) as response:
            result = json.load(response)
    except urllib.error.HTTPError as error:
        raise OpenAIClientError(\"OpenAI request failed (HTTP {})\".format(error.code)) from None
    except (urllib.error.URLError, OSError, TimeoutError):
        raise OpenAIClientError(\"Could not reach the OpenAI API\") from None
    except (ValueError, UnicodeError):
        raise OpenAIClientError(\"OpenAI returned an invalid JSON response\") from None

    if not isinstance(result, dict) or result.get(\"status\", \"completed\") "'!= "completed":
        raise OpenAIClientError("OpenAI did not complete the response")

    output = result.get("output")
    if not isinstance(output, list):
        raise OpenAIClientError("OpenAI returned no text output")
    texts = []
    for item in output:
        if not isinstance(item, dict) or item.get("type") != "message":
            continue
        content_items = item.get("content")
        if not isinstance(content_items, list):
            continue
        for content in content_items:
            if isinstance(content, dict) and content.get("type") == "output_text":
                text = content.get("text")
                if isinstance(text, str):
                    texts.append(text)
    if not texts:
        raise OpenAIClientError("OpenAI returned no text output")
    return "".join(texts)
